<script setup>
import{ref,computed,watch,onBeforeUnmount}from'vue';import{useRoute,useRouter}from'vue-router';import{api}from'@/services/api.js';import{useLearning}from'@/store.js';import{Radio,RefreshCw,Send,Check}from'@/components/app/icons.js';
const route=useRoute(),router=useRouter(),store=useLearning(),teacher=computed(()=>store.user?.role==='teacher'),items=ref([]),rooms=ref([]),lessons=ref([]),room=ref(''),lesson=ref(''),session=ref(null),question=ref(0),feedback=ref(''),answer=ref(''),reason=ref(''),error=ref(''),busy=ref(false),loading=ref(true);const createOpen=ref(false), reviewOpen=ref(false);let generation=0,inflight=false,lastActivity='',timer;
const current=computed(()=>session.value?.activities.find(a=>a.id===session.value.currentId));const request=(path,method='GET',body)=>api.request('/live'+path,{method,...(body?{body:JSON.stringify(body)}:{})});
async function refresh(){if(inflight)return;const g=generation,id=route.query.session;inflight=true;try{if(id){const next=await request('/'+encodeURIComponent(id));if(g!==generation)return;session.value=next;if(lastActivity!==next.currentId){lastActivity=next.currentId;answer.value=current.value?.answer?.answer||'';reason.value=current.value?.answer?.reason||'';feedback.value=current.value?.feedback||''}}else{const next=await request('');if(g===generation)items.value=next}if(g===generation)error.value=''}catch(e){if(g===generation)error.value=e.message}finally{inflight=false;if(g===generation)loading.value=false}}
async function run(fn){if(busy.value)return;busy.value=true;try{await fn();await refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
watch(()=>route.query.session,()=>{generation++;session.value=null;lastActivity='';answer.value=reason.value='';loading.value=true;refresh()},{immediate:true});
async function setup(){try{rooms.value=await api.request('/teaching/classes');const c=await api.request('/curriculum/courses');lessons.value=c.flatMap(c=>c.units.flatMap(u=>u.lessons));room.value=rooms.value.find(c=>c.id===String(route.query.class||store.currentClassId))?.id||rooms.value[0]?.id||'';lesson.value=lessons.value[0]?.id||''}catch(e){error.value=e.message}}setup();timer=setInterval(()=>{if(!document.hidden&&!busy.value)refresh()},3000);onBeforeUnmount(()=>{generation++;clearInterval(timer)});
watch(()=>route.query.class,id=>{if(id&&rooms.value.some(c=>c.id===String(id)))room.value=String(id)});
async function create(){await run(async()=>{const s=await request('','POST',{classId:room.value,lessonId:lesson.value});createOpen.value=false;await router.push({path:'/live',query:{session:s.id,class:room.value}})})}
async function submit(final){await run(async()=>{await request('/'+session.value.id+'/activities/'+current.value.id+'/answer','PUT',{revision:current.value.answer?.revision||0,answer:answer.value,reason:reason.value,submit:final})})}
async function end(){if(!confirm('结束后不能继续新增正式回答，原始答案和草稿保留。确认结束？'))return;await run(()=>request('/'+session.value.id+'/end','POST',{revision:session.value.revision}))}
</script>
<template><PageHeading :title="teacher?'实时课堂':'我的课堂'"><AppButton v-if="teacher&&!route.query.session" @click="createOpen=true"><Radio :size="16"/>开始课堂</AppButton><AppButton variant="ghost" aria-label="刷新课堂" @click="refresh"><RefreshCw :size="16"/></AppButton></PageHeading><AppAlert type="error" v-if="error" role="alert" class="form-error">{{error}}<AppButton variant="ghost" @click="refresh">重试</AppButton></AppAlert><p v-if="loading" role="status">读取课堂…</p><template v-if="!route.query.session"><AppDialog v-if="teacher" v-model:open="createOpen" title="开始课堂"><div class="teaching-form-row"><label>班级<NativeSelect v-model="room"><option v-for="c in rooms" :key="c.id" :value="c.id">{{c.name}}</option></NativeSelect></label><label>已发布课时<NativeSelect v-model="lesson"><option v-for="l in lessons" :key="l.id" :value="l.id">{{l.title}}</option></NativeSelect></label><AppButton :disabled="busy||!room||!lesson" @click="create"><Radio :size="16"/>开始课堂</AppButton></div></AppDialog><div class="teaching-session-list"><Surface v-for="s in items" :key="s.id"><div class="exam-list-row"><div><Status>{{s.status==='active'?'进行中':'已结束'}}</Status><h2>{{s.title}}</h2></div><RouteButton :route="'live?session='+s.id">{{s.status==='active'?'进入课堂':'回看课堂'}}</RouteButton></div></Surface><AppEmpty v-if="!items.length&&!loading" class="empty-state">暂无课堂</AppEmpty></div></template><template v-else-if="session"><div class="exam-heading"><h2>{{session.title}}</h2><RouteButton :route="'live'+(session.classId?'?class='+session.classId:'')" secondary>课堂列表</RouteButton></div><div class="exam-toolbar"><Status>{{session.status==='active'?'课堂进行中':'课堂已结束'}}</Status><template v-if="teacher"><strong>{{session.joined}} 人加入</strong><NativeSelect v-if="session.status==='active'" v-model.number="question" aria-label="推送题目"><option v-for="q in session.availableQuestions" :key="q.index" :value="q.index">{{q.index+1}}. {{q.prompt}} {{q.equation}}</option></NativeSelect><AppButton v-if="session.status==='active'" :disabled="busy" @click="run(()=>request('/'+session.id+'/push','POST',{revision:session.revision,question}))"><Send :size="16"/>推送题目</AppButton><AppButton v-if="session.status==='active'" variant="outline" :disabled="busy" @click="end">结束课堂</AppButton></template><AppButton v-else-if="!session.joined&&session.status==='active'" :disabled="busy" @click="run(()=>request('/'+session.id+'/join','POST',{}))">加入课堂</AppButton></div><Surface v-if="current"><div class="live-question-header"><span class="ops-caption">第 {{current.position}} 题</span><h2>{{current.question.prompt}}</h2><p class="exam-math">{{current.question.equation}}</p></div><template v-if="teacher"><div class="live-stats"><div v-for="(label,k) in {submitted:'已提交',correct:'核验正确',incorrect:'核验错误',unverified:'待核对'}" :key="k"><span>{{label}}</span><strong>{{current.stats[k]}}</strong></div></div><div class="table-container"><AppTable class="live-answer-table"><thead><tr><th>学生</th><th>原答案</th><th>解释</th><th>状态</th></tr></thead><tbody><tr v-for="a in current.answers" :key="a.id"><td>{{a.studentName}}</td><td>{{a.answer}}</td><td>{{a.reason}}</td><td>{{a.submittedAt?'已提交':'草稿'}}</td></tr></tbody></AppTable></div><details class="ops-disclosure"><summary>给全班讲评</summary><label class="teaching-label">讲评内容<Textarea v-model="feedback" :readonly="session.status==='ended'"/></label><AppButton v-if="session.status==='active'" :disabled="busy||!feedback.trim()" @click="run(()=>request('/'+session.id+'/activities/'+current.id+'/feedback','PUT',{text:feedback}))">发布讲评</AppButton></details></template><template v-else><label class="teaching-label">答案<Input v-model="answer" :readonly="!!current.answer?.submittedAt||session.status==='ended'"/></label><label class="teaching-label">我的解释<Textarea v-model="reason" :readonly="!!current.answer?.submittedAt||session.status==='ended'"/></label><div v-if="session.joined&&session.status==='active'&&!current.answer?.submittedAt" class="exam-toolbar"><AppButton variant="outline" :disabled="busy" @click="submit(false)">保存草稿</AppButton><AppButton :disabled="busy||!answer.trim()" @click="submit(true)"><Check :size="16"/>提交回答</AppButton></div><Status v-if="current.answer?.submittedAt">已提交，原答保留</Status><p v-if="current.feedback" class="live-feedback">{{current.feedback}}</p></template></Surface><AppEmpty v-else class="empty-state">{{teacher?'请选择题目并推送':'等待教师推送活动'}}</AppEmpty><details v-if="session.status==='ended'" class="teaching-history ops-disclosure"><summary>课堂记录 　 {{session.activities.length}} 次活动</summary><article v-for="a in session.activities" :key="a.id"><h3>{{a.position}}. {{a.question.prompt}} {{a.question.equation}}</h3><template v-if="teacher"><p v-for="x in a.answers" :key="x.id">{{x.studentName}} 　 {{x.answer}} 　 {{x.reason}} 　 {{x.submittedAt?'已提交':'草稿留存'}}</p></template><template v-else-if="a.answer"><Status>{{a.answer.submittedAt?'已提交':'草稿留存'}}</Status><p>{{a.answer.answer}} 　 {{a.answer.reason}}</p></template><p>{{a.feedback}}</p></article><RouteButton v-if="session.taskId" :route="(teacher?'insights':'result')+'?task='+session.taskId" secondary>查看学习记录</RouteButton></details></template></template>
